import Foundation
import HTTPCore
import HTTPTestSupport
import Network
import NetworkTransport
import Synchronization

// Test support for the QUIC adapter (#0098). Everything binds or connects to 127.0.0.1 with
// port 0 (AGENTS.md), and the identity is the gitignored test identity loaded in memory only.

/// The test identity (#0072), generated by `scripts/make-test-identity.sh` if missing.
func quicTestIdentity() throws -> (identity: TLSIdentity, certificateDER: [UInt8]) {
    let material = try TestIdentity.load()
    let identity = try TLSIdentity(pkcs12: material.pkcs12, password: TestIdentity.password)
    return (identity, material.certificateDER)
}

/// Transport settings small enough to make limits observable in tests.
func testQUICConfiguration(maxStreamsBidirectional: Int = 100, alpn: [String] = ["h3"]) -> QUICConfiguration {
    QUICConfiguration(alpn: alpn, maxStreamsBidirectional: maxStreamsBidirectional, idleTimeoutMilliseconds: 20_000)
}

/// A started QUIC listener on 127.0.0.1, port 0.
func makeQUICListener(quic: QUICConfiguration = testQUICConfiguration()) async throws -> QUICListener {
    let (identity, _) = try quicTestIdentity()
    let listener = try QUICListener(
        configuration: .init(host: "127.0.0.1", port: 0, quic: quic), identity: identity)
    try await listener.start()
    return listener
}

/// A client connection to `port` that pins the test certificate.
func connectQUIC(port: UInt16, quic: QUICConfiguration = testQUICConfiguration()) async throws -> QUICConnection {
    let (_, certificate) = try quicTestIdentity()
    return try await QUICConnection.connect(
        host: "127.0.0.1", port: port,
        configuration: .init(quic: quic, peerVerification: .pinnedCertificate(certificate), connectTimeout: .seconds(10)))
}

/// Takes the next accepted connection.
func accept(_ listener: QUICListener) async throws -> QUICConnection {
    var iterator = listener.connections.makeAsyncIterator()
    guard let connection = try await iterator.next() else { throw TransportError.closed }
    return connection
}

/// Takes the next inbound stream of a multiplexed transport.
func acceptStream<M: MultiplexedTransport>(_ transport: M) async throws -> M.Stream {
    var iterator = transport.inboundStreams.makeAsyncIterator()
    guard let stream = try await iterator.next() else { throw TransportError.closed }
    return stream
}

/// Receives until end of stream.
func receiveAll(_ stream: some ByteStreamTransport, maxLength: Int = 64 * 1024) async throws -> ByteBuffer {
    var buffer = ByteBuffer()
    while try await stream.receive(into: &buffer, maxLength: maxLength) > 0 {}
    return buffer
}

/// A client connection and the matching server connection.
func makeQUICPair(
    quic: QUICConfiguration = testQUICConfiguration()
) async throws -> (listener: QUICListener, client: QUICConnection, server: QUICConnection) {
    let listener = try await makeQUICListener(quic: quic)
    let client = try await connectQUIC(port: listener.port, quic: quic)
    // The server group is handed over once usable; with a Network.framework client that is
    // when the group is ready.
    let server = try await accept(listener)
    return (listener, client, server)
}

// MARK: - Raw Network.framework QUIC client

/// A bare `NWConnectionGroup` QUIC client, so the adapter is checked against Network.framework
/// directly and not only against itself.
final class RawQUICClient: Sendable {
    let group: NWConnectionGroup
    let queue = DispatchQueue(label: "sws.test.rawquic")
    private let readyWaiter = Mutex<UnsafeContinuation<Void, any Error>?>(nil)
    private let inbound = Mutex<[NWConnection]>([])

    init(port: UInt16, certificate: [UInt8], alpn: [String] = ["h3"]) {
        let quic = NWProtocolQUIC.Options(alpn: alpn)
        sec_protocol_options_set_verify_block(quic.securityProtocolOptions, { _, trust, complete in
            let secTrust = sec_trust_copy_ref(trust).takeRetainedValue()
            let chain = SecTrustCopyCertificateChain(secTrust) as? [SecCertificate]
            let leaf = chain?.first.map { [UInt8](SecCertificateCopyData($0) as Data) }
            complete(leaf == certificate)
        }, DispatchQueue.global())
        group = NWConnectionGroup(
            with: NWMultiplexGroup(to: .hostPort(host: .ipv4(.loopback), port: NWEndpoint.Port(rawValue: port)!)),
            using: NWParameters(quic: quic))
    }

    func start() async throws {
        try await withUnsafeThrowingContinuation { (continuation: UnsafeContinuation<Void, any Error>) in
            readyWaiter.withLock { $0 = continuation }
            // Required before start (spike gotcha 3).
            group.newConnectionHandler = { [self] stream in inbound.withLock { $0.append(stream) } }
            group.stateUpdateHandler = { [self] state in
                let result: Result<Void, any Error>
                switch state {
                case .ready: result = .success(())
                case .failed(let error): result = .failure(error)
                case .cancelled: result = .failure(TransportError.closed)
                default: return
                }
                let waiter = readyWaiter.withLock { value in
                    defer { value = nil }
                    return value
                }
                waiter?.resume(with: result)
            }
            group.start(queue: queue)
        }
    }

    /// Opens a bidirectional stream and waits until it is ready.
    func openStream() async throws -> NWConnection {
        guard let stream = NWConnection(from: group) else { throw TransportError.closed }
        try await start(stream)
        return stream
    }

    func start(_ stream: NWConnection) async throws {
        let waiter = Mutex<UnsafeContinuation<Void, any Error>?>(nil)
        try await withUnsafeThrowingContinuation { (continuation: UnsafeContinuation<Void, any Error>) in
            waiter.withLock { $0 = continuation }
            stream.stateUpdateHandler = { state in
                let result: Result<Void, any Error>
                switch state {
                case .ready: result = .success(())
                case .failed(let error): result = .failure(error)
                case .cancelled: result = .failure(TransportError.closed)
                default: return
                }
                let pending = waiter.withLock { value in
                    defer { value = nil }
                    return value
                }
                pending?.resume(with: result)
            }
            stream.start(queue: queue)
        }
    }

    /// Server-initiated streams received so far.
    var inboundStreams: [NWConnection] { inbound.withLock { $0 } }

    func cancel() {
        for stream in inboundStreams { stream.cancel() }
        group.cancel()
    }

    static func send(_ stream: NWConnection, _ bytes: [UInt8], final: Bool) async throws {
        try await withUnsafeThrowingContinuation { (continuation: UnsafeContinuation<Void, any Error>) in
            stream.send(
                content: bytes.isEmpty ? nil : Data(bytes), contentContext: final ? .finalMessage : .defaultMessage,
                isComplete: true, completion: .contentProcessed { error in
                    if let error { continuation.resume(throwing: error) } else { continuation.resume() }
                })
        }
    }

    /// Receives until FIN or an error; returns the bytes, whether FIN arrived, and the error.
    static func receiveAll(_ stream: NWConnection) async -> (bytes: [UInt8], fin: Bool, error: NWError?) {
        var all: [UInt8] = []
        while true {
            let (data, isComplete, error) = await withUnsafeContinuation {
                (continuation: UnsafeContinuation<(Data?, Bool, NWError?), Never>) in
                stream.receive(minimumIncompleteLength: 1, maximumLength: 65536) { data, _, isComplete, error in
                    continuation.resume(returning: (data, isComplete, error))
                }
            }
            if let data { all += data }
            if error != nil || isComplete || (data?.isEmpty ?? true) { return (all, isComplete && error == nil, error) }
        }
    }

    static func streamApplicationErrorCode(_ stream: NWConnection) -> UInt64? {
        (stream.metadata(definition: NWProtocolQUIC.definition) as? NWProtocolQUIC.Metadata)?.streamApplicationErrorCode
    }

    static func streamID(_ stream: NWConnection) -> UInt64? {
        (stream.metadata(definition: NWProtocolQUIC.definition) as? NWProtocolQUIC.Metadata)?.streamIdentifier
    }
}
